# Generated by manage.py generate_test_cases.
from django.test import override_settings

from bloomerp.config.definition import BloomerpAuthSettings, BloomerpConfig, SessionAuthSettings
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestLoginView(BloomerpAPIViewTestCase):
    """Tests class `LoginView` from `bloomerp/views/api/auth/login.py`."""

    view_name = 'api_login'

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="Username and password create an authenticated session",
                description=(
                    "UC: A user signs in with the default username identifier.\n"
                    "Expected Result: The API authenticates the user and establishes a session."
                ),
                method="POST",
                content_type="application/json",
                data={"username": "johndoe", "password": "testpass123"},
                expected=ExpectedResult(response_validators=self.login_created_session),
            ),
            RequestScenario(
                name="Email can be configured as API login identifier",
                description=(
                    "UC: Session authentication is configured to use email.\n"
                    "Expected Result: The user's email and password authenticate successfully."
                ),
                method="POST",
                content_type="application/json",
                data={"email": "johndoe@example.com", "password": "testpass123"},
                prepare=self.enable_email_login,
                cleanup=self.disable_settings_override,
                expected=ExpectedResult(response_validators=self.json_key_equals("authenticated", True)),
            ),
        ]

    def enable_email_login(self, _scenario):
        self.settings_override = override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(
                auto_generate_api_endpoints=True,
                auth=BloomerpAuthSettings(
                    session=SessionAuthSettings(login_identifier="email")
                ),
            )
        )
        self.settings_override.enable()

    def disable_settings_override(self, _scenario):
        self.settings_override.disable()

    def login_created_session(self, response):
        return (
            response.json().get("authenticated") is True
            and self.client.session.get("_auth_user_id") == str(self.normal_user.pk)
        )
